head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gSeq;
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.vScrenID = 'ULDSTF36000.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 일주일전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();
};


// 화면로딩시 검색
scwin.fn_initSearch = function() {
    fn_CheckCond();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !매매거래정지예정--;
클릭-- > function() {
    /*
    	// 일자 체크
    	if( getObjectValue(edt_FromDate).length < 8) {
    		alert("일자 올바르게 입력하십시오." );
    		edt_FromDate.focus();
    		return;		
    	}		

    	// 일자 체크
    	if( getObjectValue(edt_ToDate).length < 8) {
    		alert("일자 올바르게 입력하십시오." );
    		edt_ToDate.focus();
    		return;		
    	}		
    	*/

    scwin.gDepCd = $c.stf.getObjectValue(cmb_TeamList);
    scwin.gEmpNo = $c.stf.getObjectValue(cmb_EmpList);
    //alert(gDepCd +'-' +gEmpNo);
    fn_Search();
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
scwin.setChkValue = function(obj, booleanVal) {
    //return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !매매거래정지예정--;
클릭-- > function() {
    vCurrPageNo = 0;
    var url_list = "/TrdHaltSchdl.do?method=listTrdHaltSchdl&inputMessageId=HALTSCHDLCOND_IN" + "&outputMessageId=HALTSCHDLLIST_OUT";
    var url_cond = "&ISUR_NM_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&DEP_CD=" + scwin.gDepCd + "&EMP_NO=" + scwin.gEmpNo + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    $c.cm.ShowWin(grd_haltschdl_list);
    // 그리드의 데이타 조회
    dts_haltschdl_list.DataID = encodeURI(url_list + url_cond);
    dts_haltschdl_list.reset();
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_haltschdl_list.getCellData(eval(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_haltschdl_list.getCellData(eval(obj), "FORM_CD");
    scwin.gFormVer = dts_haltschdl_list.getCellData(eval(obj), "FORM_VER");
    scwin.gIsurCd = dts_haltschdl_list.getCellData(eval(obj), "ISUR_CD");
    scwin.gSeq = dts_haltschdl_list.getCellData(eval(obj), "SEQ");

    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);
    //alert("부모창 gSeq:"+gSeq);

};
scwin.grd_haltschdl_list_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "DOC_TITLE") {
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, 'R');
    } else if (colid == "HALT_SCHDL_DD" || colid == "HALT_RELEAS_SCHDL_DD" ||
        colid == "LIST_SCHDL_DD") {
        var url = "/dsclmgt/ULDSTF36002.gfm";
        var winTitle = "매매거래정지예정일 관리";
        await $c.frame.CreateFrame("HALTSCHDL_INFO" + scwin.gSeq, url, winTitle, 250, 100, 640, 380, "window", 0, 0, true);
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.dts_dep_OnLoadError = function() {
    $c.stf.alert_error(dts_dep);
};
scwin.dts_emp_OnLoadError = function() {
    $c.stf.alert_error(dts_emp);
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    // 유가일때만 디폴트 로그인한 사용자	
    if (js_market == '1') {
        $c.stf.setObjectValue(cmb_TeamList, js_dep_cd);
    }
};
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    // 유가일때만 디폴트 로그인한 사용자	
    if (js_market == '1') {
        $c.stf.setObjectValue(cmb_EmpList, js_emp_no);
    }
    // 화면로딩할때 코드셋팅후 조회한다. : 시간차땜시 요기로 옮겼음
    scwin.fn_initSearch();
};
scwin.cmb_TeamList_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.dts_haltschdl_list_OnLoadError = function() {
    $c.stf.alert_error(dts_haltschdl_list);
    $c.cm.CloseWin('', grd_haltschdl_list);
};
scwin.dts_haltschdl_list_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_haltschdl_list);
    if (dts_haltschdl_list.errorMsg) {
        $c.win.alert(dts_haltschdl_list.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page); //총 건수

    }
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_haltschdl_list, "매매거래정지예정 목록", "", "2");
};
scwin.btn_New_onclick = async function() {
    var url = "/dsclmgt/ULDSTF36001.gfm";
    var winTitle = "매매거래정지예정일 관리";
    await $c.frame.CreateFrame("HALTSCHDL_INFO", url, winTitle, 250, 150, 640, 340, "window", 0, 0, true);
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    scwin.fn_SetCode();
    $c.stf.showObj(panel_opt, false); //  공시일기준 검색이 불가 -? 히든시킴
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    //fn_initSearch();		

};
